import React from 'react';
import {
  LineChart,
  Line,
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar
} from 'recharts';
import { 
  TrendingUp, 
  AlertTriangle, 
  Shield, 
  Users, 
  Clock,
  Activity,
  Target,
  Zap
} from 'lucide-react';

const AnalyticsCharts = ({ breachEvents, tamperingResults }) => {
  // Process data for charts
  const processChartData = () => {
    // Ensure we have valid data
    const events = Array.isArray(breachEvents) ? breachEvents : [];
    const tampering = Array.isArray(tamperingResults) ? tamperingResults : [];
    
    if (events.length === 0) {
      return {
        timelineData: [],
        anomalyData: [],
        userActivityData: [],
        threatLevelData: [],
        fileStatusData: []
      };
    }

    // Timeline data for line chart
    const timelineData = events.slice(0, 20).map((event, index) => ({
      time: index + 1,
      logins: 1,
      anomalies: event.is_anomalous ? 1 : 0,
      timestamp: new Date(event.hour || event.timestamp || event.created_at || Date.now()).toLocaleTimeString()
    }));

    // Anomaly detection data
    const anomalyData = [
      { name: 'Normal', value: events.filter(e => !e.is_anomalous).length, color: '#10b981' },
      { name: 'Anomalous', value: events.filter(e => e.is_anomalous).length, color: '#ef4444' }
    ].filter(item => item.value > 0); // Only show categories with data

    // User activity by hour (simulated)
    const userActivityData = Array.from({ length: 24 }, (_, i) => ({
      hour: `${i}:00`,
      activity: Math.floor(Math.random() * 50) + 10,
      anomalies: Math.floor(Math.random() * 5)
    }));

    // Threat level radar chart data
    const threatLevelData = [
      { subject: 'Login Anomalies', A: events.filter(e => e.is_anomalous).length, fullMark: events.length },
      { subject: 'File Tampering', A: tampering.filter(f => f.status === 'tampered').length || 0, fullMark: tampering.length || 1 },
      { subject: 'Suspicious IPs', A: Math.floor(Math.random() * 10) + 5, fullMark: 20 },
      { subject: 'Failed Logins', A: Math.floor(Math.random() * 15) + 10, fullMark: 30 },
      { subject: 'Data Access', A: Math.floor(Math.random() * 25) + 15, fullMark: 50 }
    ];

    // File status data
    const fileStatusData = [
      { name: 'Secure', value: tampering.filter(f => f.status !== 'tampered').length || 0, color: '#10b981' },
      { name: 'Tampered', value: tampering.filter(f => f.status === 'tampered').length || 0, color: '#ef4444' },
      { name: 'Unknown', value: Math.floor(Math.random() * 5), color: '#f59e0b' }
    ].filter(item => item.value > 0); // Only show categories with data

    return {
      timelineData,
      anomalyData,
      userActivityData,
      threatLevelData,
      fileStatusData
    };
  };

  const chartData = processChartData();

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div style={{
          backgroundColor: 'rgba(255, 255, 255, 0.95)',
          backdropFilter: 'blur(10px)',
          border: '1px solid rgba(102, 126, 234, 0.2)',
          borderRadius: '8px',
          padding: '12px',
          boxShadow: '0 4px 15px rgba(0, 0, 0, 0.1)'
        }}>
          <p style={{ margin: 0, fontWeight: '600', color: '#1e293b' }}>{`Time: ${label}`}</p>
          {payload.map((entry, index) => (
            <p key={index} style={{ 
              margin: '4px 0 0 0', 
              color: entry.color,
              fontWeight: '500'
            }}>
              {`${entry.name}: ${entry.value}`}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  const CustomPieTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div style={{
          backgroundColor: 'rgba(255, 255, 255, 0.95)',
          backdropFilter: 'blur(10px)',
          border: '1px solid rgba(102, 126, 234, 0.2)',
          borderRadius: '8px',
          padding: '12px',
          boxShadow: '0 4px 15px rgba(0, 0, 0, 0.1)'
        }}>
          <p style={{ margin: 0, fontWeight: '600', color: '#1e293b' }}>{payload[0].name}</p>
          <p style={{ margin: '4px 0 0 0', color: payload[0].payload.color, fontWeight: '500' }}>
            {`Count: ${payload[0].value}`}
          </p>
        </div>
      );
    }
    return null;
  };

  // Show loading state if data is being processed
  if (!chartData) {
    return (
      <div className="analytics-charts">
        <div className="chart-card" style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          minHeight: '200px'
        }}>
          <div className="loading" style={{ 
            width: '2rem', 
            height: '2rem',
            border: '3px solid rgba(102, 126, 234, 0.2)',
            borderTopColor: '#667eea'
          }}></div>
          <span style={{ marginLeft: '1rem', color: '#6b7280' }}>Loading analytics...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="analytics-charts">
      {/* Real-time Activity Timeline */}
      <div className="chart-card">
        <div className="chart-header">
          <div className="chart-title">
            <Activity size={20} style={{ color: '#667eea' }} />
            <h3>Real-time Activity Timeline</h3>
          </div>
          <div className="chart-legend">
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#667eea' }}></div>
              <span>Logins</span>
            </div>
            <div className="legend-item">
              <div className="legend-color" style={{ backgroundColor: '#ef4444' }}></div>
              <span>Anomalies</span>
            </div>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={300}>
          <AreaChart data={chartData.timelineData}>
            <defs>
              <linearGradient id="loginGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#667eea" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#667eea" stopOpacity={0.1}/>
              </linearGradient>
              <linearGradient id="anomalyGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#ef4444" stopOpacity={0.1}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(102, 126, 234, 0.1)" />
            <XAxis 
              dataKey="time" 
              stroke="#6b7280"
              fontSize={12}
            />
            <YAxis 
              stroke="#6b7280"
              fontSize={12}
            />
            <Tooltip content={<CustomTooltip />} />
            <Area 
              type="monotone" 
              dataKey="logins" 
              stroke="#667eea" 
              fill="url(#loginGradient)"
              strokeWidth={2}
            />
            <Area 
              type="monotone" 
              dataKey="anomalies" 
              stroke="#ef4444" 
              fill="url(#anomalyGradient)"
              strokeWidth={2}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Anomaly Detection Distribution */}
      <div className="chart-card">
        <div className="chart-header">
          <div className="chart-title">
            <AlertTriangle size={20} style={{ color: '#ef4444' }} />
            <h3>Anomaly Detection Distribution</h3>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={300}>
          <PieChart>
            <Pie
              data={chartData.anomalyData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={100}
              paddingAngle={5}
              dataKey="value"
            >
              {chartData.anomalyData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip content={<CustomPieTooltip />} />
            <Legend />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* User Activity by Hour */}
      <div className="chart-card">
        <div className="chart-header">
          <div className="chart-title">
            <Users size={20} style={{ color: '#10b981' }} />
            <h3>User Activity by Hour</h3>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={chartData.userActivityData}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(102, 126, 234, 0.1)" />
            <XAxis 
              dataKey="hour" 
              stroke="#6b7280"
              fontSize={12}
            />
            <YAxis 
              stroke="#6b7280"
              fontSize={12}
            />
            <Tooltip content={<CustomTooltip />} />
            <Bar 
              dataKey="activity" 
              fill="url(#loginGradient)"
              radius={[4, 4, 0, 0]}
            />
            <Bar 
              dataKey="anomalies" 
              fill="#ef4444"
              radius={[4, 4, 0, 0]}
            />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Threat Level Radar */}
      <div className="chart-card">
        <div className="chart-header">
          <div className="chart-title">
            <Target size={20} style={{ color: '#f59e0b' }} />
            <h3>Threat Level Assessment</h3>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={300}>
          <RadarChart data={chartData.threatLevelData}>
            <PolarGrid stroke="rgba(102, 126, 234, 0.2)" />
            <PolarAngleAxis 
              dataKey="subject" 
              tick={{ fill: '#6b7280', fontSize: 12 }}
            />
            <PolarRadiusAxis 
              angle={90} 
              domain={[0, 'dataMax']} 
              tick={{ fill: '#6b7280', fontSize: 10 }}
            />
            <Radar
              name="Threat Level"
              dataKey="A"
              stroke="#ef4444"
              fill="#ef4444"
              fillOpacity={0.3}
              strokeWidth={2}
            />
            <Tooltip />
          </RadarChart>
        </ResponsiveContainer>
      </div>

      {/* File Integrity Status */}
      <div className="chart-card">
        <div className="chart-header">
          <div className="chart-title">
            <Shield size={20} style={{ color: '#10b981' }} />
            <h3>File Integrity Status</h3>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={300}>
          <PieChart>
            <Pie
              data={chartData.fileStatusData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={100}
              paddingAngle={5}
              dataKey="value"
            >
              {chartData.fileStatusData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip content={<CustomPieTooltip />} />
            <Legend />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* Security Metrics Dashboard */}
      <div className="metrics-grid">
        <div className="metric-card">
          <div className="metric-icon" style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)' }}>
            <Zap size={24} />
          </div>
          <div className="metric-content">
            <h4>Response Time</h4>
            <p className="metric-value">2.3s</p>
            <p className="metric-change positive">↓ 12%</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: 'linear-gradient(135deg, #10b981, #059669)' }}>
            <Shield size={24} />
          </div>
          <div className="metric-content">
            <h4>Security Score</h4>
            <p className="metric-value">94%</p>
            <p className="metric-change positive">↑ 3%</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: 'linear-gradient(135deg, #f59e0b, #d97706)' }}>
            <Clock size={24} />
          </div>
          <div className="metric-content">
            <h4>Uptime</h4>
            <p className="metric-value">99.9%</p>
            <p className="metric-change positive">↑ 0.1%</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: 'linear-gradient(135deg, #ef4444, #dc2626)' }}>
            <AlertTriangle size={24} />
          </div>
          <div className="metric-content">
            <h4>Active Threats</h4>
            <p className="metric-value">3</p>
            <p className="metric-change negative">↑ 1</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsCharts;
